import gurobipy as gp
from gurobipy import GRB

# Create a new model with the provided environment
env = gp.Env()
model = gp.Model(env=env)

# Define variables
L = model.addVar(vtype=GRB.INTEGER, name="L", lb=0)
S = {w: model.addVar(vtype=GRB.INTEGER, name=f"S_{w}", lb=0) for w in range(1, 8)}
C = {2: model.addVar(vtype=GRB.INTEGER, name="C_2", lb=0),
     4: model.addVar(vtype=GRB.INTEGER, name="C_4", lb=0),
     5: model.addVar(vtype=GRB.INTEGER, name="C_5", lb=0)}
P = {w: model.addVar(vtype=GRB.INTEGER, name=f"P_{w}", lb=0, ub=2) for w in range(4, 8)}

# Define the demand for each week
demand = [6, 9, 12, 8, 5, 7, 4]

# Add constraints for each week
for w in range(1, 8):
    if w == 1:
        model.addConstr(L + S[w] >= demand[w-1], name=f"week_{w}")
    elif w == 2:
        model.addConstr(L + S[w] + C[w] >= demand[w-1], name=f"week_{w}")
    elif w == 3:
        model.addConstr(L + S[w] >= demand[w-1], name=f"week_{w}")
    elif w in [4,5]:
        model.addConstr(L + S[w] + C[w] + P[w] >= demand[w-1], name=f"week_{w}")
    else:  # weeks 6 and 7
        if w == 6:
            model.addConstr(L + S[w] + P[w] >= demand[w-1], name=f"week_{w}")
        elif w == 7:
            model.addConstr(L + S[w] + P[w] >= demand[w-1], name=f"week_{w}")

# Set the objective function to minimize total cost
model.setObjective(240 * L + sum(390 * S[w] for w in range(1, 8)) +
                   sum(220 * C[w] for w in [2,4,5]) + 
                   sum(190 * P[w] for w in range(4, 8)), GRB.MINIMIZE)

# Optimize the model
model.optimize()

# Check if solution is optimal and print the objective value
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No optimal solution found.")

import gurobipy as gp
from gurobipy import GRB

# Read input data
distances = {
    (0,1): 12, (0,2): 8,
    (1,2):5, (1,3):9,
    (2,4):7, (3,4):6,
    (3,5):11, (4,6):10,
    (5,6):4, (5,7):8,
    (6,8):7, (7,8):6
}

# Create a list of all nodes
nodes = [0, 1, 2, 3, 4, 5, 6, 7, 8]

# Build the model
env = gp.Env()
model = gp.Model(env=env)

# Decision variables: x[i][j] is 1 if edge i->j exists
x = {}
for i in nodes:
    for j in nodes:
        if i != j and (i,j) in distances:
            x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

# Variables to track the number of nodes in each subtree
y = {}
for i in nodes:
    y[i] = model.addVar(vtype=GRB.INTEGER, name=f"y_{i}")

# Objective: minimize total distance
model.setObjective(gp.quicksum(distances[i,j] * x[i,j] for i,j in distances), GRB.MINIMIZE)

# Constraints

# Connectivity constraint: each node except 0 must have at least one incoming edge
for i in nodes:
    if i != 0:
        model.addConstr(gp.quicksum(x[j,i] for j in nodes if (j, i) in distances), GRB.GE, 1)

# Subtree size constraints
model.addConstr(y[0], GRB.EQUAL, 9)
for i in nodes:
    if i != 0:
        model.addConstr(y[i], GRB.LESS_EQUAL, 3)

# Flow constraints to compute y[i]
for i in nodes:
    expr = gp.LinExpr()
    expr.addTerm(1.0)  # The node itself
    for j in nodes:
        if (i, j) in distances:
            expr += x[i,j] * y[j]
    model.addConstr(expr, GRB.EQUAL, y[i])

# Optimize the model
model.optimize()

# Check if solution is optimal and print the objective value
if model.status == GRB.Status.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No optimal solution found")

from gurobipy import *

env = gp.Env()
model = gp.Model(env=env)

# Sets
products = ['A', 'B', 'C', 'D', 'E']
stores = ['Store1', 'Store2', 'Store3']
trucks = range(4)  # 0 to 3

# Parameters
weight = {'A': 2, 'B': 3, 'C': 1, 'D': 4, 'E': 2}
demand = {
    'Store1': {'A': 2, 'B': 1, 'C': 3},
    'Store2': {'A': 1, 'D': 2, 'E': 1},
    'Store3': {'B': 3, 'C': 2, 'E': 1}
}

# Decision variables
y = {}
x = {}

for j in trucks:
    y[j] = model.addVar(vtype=GRB.BINARY, name=f'y_{j}')
    for s in stores:
        for p in products:
            x[(j, s, p)] = model.addVar(lb=0, ub=demand[s].get(p, 0), vtype=GRB.INTEGER, name=f'x_{j}_{s}_{p}')

model.update()

# Objective: minimize number of trucks used
model.setObjective(sum(y[j] for j in trucks), GRB.MINIMIZE)

# Constraints

# 1. Meet demand for each product and store
for s in stores:
    for p in demand[s]:
        qty = demand[s][p]
        model.addConstr(sum(x[(j, s, p)] for j in trucks) == qty, f'demand_{s}_{p}')

# 2. Truck capacity constraints
for j in trucks:
    total_weight = sum(x[(j, s, p)] * weight[p] for s in stores for p in products)
    model.addConstr(total_weight <= 15, f'truck_capacity_{j}')

# 3. Link x and y variables: x[j][s][p] <= M*y[j], where M=3
M = 3
for j in trucks:
    for s in stores:
        for p in products:
            if demand[s].get(p, 0) > 0:
                model.addConstr(x[(j, s, p)] <= M * y[j], f'link_{j}_{s}_{p}')

model.update()

# Optimize
model.optimize()

if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No solution found")

import gurobipy as gp
from gurobipy import GRB

# Data
trucks = ['t1', 't2', 't3']
capacities = {'t1': 8, 't2': 10, 't3': 12}
stores = ['s1', 's2', 's3', 's4', 's5']
demands = {'s1': 3, 's2': 4, 's3': 5, 's4': 2, 's5': 6}
distances = {'s1': 15, 's2': 20, 's3': 25, 's4': 30, 's5': 35}

# Create model
env = gp.Env()
model = gp.Model(env=env)

# Variables
x = {}
max_dist = {}

for t in trucks:
    for s in stores:
        x[t][s] = model.addVar(vtype=GRB.BINARY)
    max_dist[t] = model.addVar()

# Objective: Minimize total distance (twice the maximum distance per truck)
model.setObjective(gp.quicksum(2 * max_dist[t] for t in trucks), GRB.MINIMIZE)

# Constraints

# Each store is assigned to exactly one truck
for s in stores:
    model.addConstr(gp.quicksum(x[t][s] for t in trucks) == 1, f"Store_{s}")

# Truck capacity constraints
for t in trucks:
    total_demand = gp.quicksum(demands[s] * x[t][s] for s in stores)
    model.addConstr(total_demand <= capacities[t], f"Capacity_{t}")

# Max distance constraints: max_dist[t] >= distance[s] if x[t][s] is 1
for t in trucks:
    for s in stores:
        model.addConstr(max_dist[t] >= distances[s] * x[t][s], f"MaxDist_{t}_{s}")

# Set upper bounds on max_dist to help solving
for t in trucks:
    model.addConstr(max_dist[t] <= 35, f"UpperBound_{t}")

model.optimize()

if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No solution found")

