from gurobipy import GRB

Production_cost = {'A': 100, 'B': 120, 'C': 150}
Yield_capacity = {'A': 500, 'B': 400, 'C': 600}
Water_usage = {'A': 6, 'B': 8, 'C': 6}
Fertilizer_usage = {'A': 5, 'B': 4, 'C': 3}
Demand = {1: 200, 2: 300, 3: 400, 4: 500}

Transport = {
    'A': [20, 25, 30, 15],
    'B': [22, 26, 32, 18],
    'C': [18, 24, 28, 14]
}

model = gp.Model(env=env)

x = {}
for i in ['A', 'B', 'C']:
    for j in [1, 2, 3, 4]:
        x[i, j] = model.addVar(lb=0, name=f"x_{i}_{j}")

# Objective function
obj = 0
for i in ['A', 'B', 'C']:
    for j in [1, 2, 3, 4]:
        trans_cost = Transport[i][j - 1]
        cost_per_ton = Production_cost[i] + trans_cost
        obj += cost_per_ton * x[i, j]

model.setObjective(obj, GRB.MINIMIZE)

# Supply constraints
for i in ['A', 'B', 'C']:
    sum_supply = 0
    for j in [1, 2, 3, 4]:
        sum_supply += x[i, j]
    model.addConstr(sum_supply <= Yield_capacity[i], f"Supply_{i}")

# Demand constraints
for j in [1, 2, 3, 4]:
    sum_demand = 0
    for i in ['A', 'B', 'C']:
        sum_demand += x[i, j]
    model.addConstr(sum_demand >= Demand[j], f"Demand_{j}")

# Compute total shipped
total_shipped = 0
for i in ['A', 'B', 'C']:
    for j in [1, 2, 3, 4]:
        total_shipped += x[i, j]

