fert_usage = 0
for i in ['A', 'B', 'C']:
    for j in [1, 2, 3, 4]:
        water_usage += Water_usage[i] * x[i, j]
        fert_usage += Fertilizer_usage[i] * x[i, j]

model.addConstr(water_usage <= 7 * total_shipped, "Water_Constraint")
model.addConstr(fert_usage <= 4 * total_shipped, "Fertilizer_Constraint")

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
