plants = ['P1', 'P2']
dcs = ['DC1', 'DC2', 'DC3']
regions = ['R1', 'R2', 'R3', 'R4']

# Parameters
production_p1 = [250, 250, 260, 260, 270, 270]
production_p2 = [200, 200, 210, 210, 220, 220]

# Fixed costs for DCs
fixed_cost = {'DC1': 10000, 'DC2': 12000, 'DC3': 9000}

# Storage capacities
storage_cap = {'DC1': 300, 'DC2': 350, 'DC3': 280}

# Transportation costs from plants to DCs
transp_cost_plant_dc = {
    ('P1', 'DC1'): 5,
    ('P1', 'DC2'): 7,
    ('P1', 'DC3'): 6,
    ('P2', 'DC1'): 8,
    ('P2', 'DC2'): 4,
    ('P2', 'DC3'): 7
}

# Transportation costs from DCs to regions
transp_cost_dc_region = {
    ('DC1', 'R1'): 3,
    ('DC1', 'R2'): 4,
    ('DC1', 'R3'): 5,
    ('DC1', 'R4'): 6,
    ('DC2', 'R1'): 5,
    ('DC2', 'R2'): 3,
    ('DC2', 'R3'): 4,
    ('DC2', 'R4'): 5,
    ('DC3', 'R1'): 4,
    ('DC3', 'R2'): 5,
    ('DC3', 'R3'): 3,
    ('DC3', 'R4'): 4
}

# Inventory holding costs
holding_cost = {'DC1': 2.0, 'DC2': 2.5, 'DC3': 1.8}

# Disposal cost and shortage cost
disposal_cost = 1
shortage_cost = 50

# Demand for each region per month
demand = {
    'R1': [100, 110, 120, 130, 140, 150],
    'R2': [80, 85, 90, 95, 100, 105],
    'R3': [120, 125, 130, 135, 140, 145],
    'R4': [60, 65, 70, 75, 80, 85]
}

# Initial inventory for DC1 in Month 1
initial_inv_dc1 = {1: {'Month0': 10, 'Month-1': 5}}

# Decision variables

# Binary variables for DC operation
d_open = {}
for m in months:
    for dc in dcs:
        d_open[(m, dc)] = model.addVar(vtype=GRB.BINARY, name=f"DC_{dc}_open_month_{m}")

# Production variables
prod_p1 = [model.addVar(lb=0, ub=production_p1[i], vtype=GRB.INTEGER, name=f"P1_prod_month_{i+1}") for i in range(6)]
prod_p2 = [model.addVar(lb=0, ub=production_p2[i], vtype=GRB.INTEGER, name=f"P2_prod_month_{i+1}") for i in range(6)]

# Shipment variables from plants to DCs
ship_plant_dc = {}
for m in months:
    for p in plants:
        for dc in dcs:
            ship_plant_dc[(m, p, dc)] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"Ship_{p}_to_{dc}_month_{m}")

# Inventory variables at DCs
inv_dc_month = {}
for m in months:
    for dc in dcs:
        for t in [1, 2]:
            inv_dc_month[(m, dc, t)] = model.addVar(lb=0, ub=storage_cap[dc], vtype=GRB.INTEGER, name=f"Inv_{dc}_month_{m}_t_{t}")

# Shipment variables from DCs to regions
ship_dc_region = {}
for m in months:
    for dc in dcs:
        for r in regions:
            ship_dc_region[(m, dc, r)] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"Ship_{dc}_to_{r}_month_{m}")

# Unmet demand variables
demand_unmet = {}
for m in months:
    for r in regions:
        demand_unmet[(m, r)] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"Unmet_demand_{r}_month_{m}")

# Constraints

# 1. Production constraints for plants
for i in range(6):
    model.addConstr(prod_p1[i] <= production_p1[i], f"P1_prod_max_month_{i+1}")
    model.addConstr(prod_p2[i] <= production_p2[i], f"P2_prod_max_month_{i+1}")

# 2. Shipment from plants to DCs
for m in months:
    for p in plants:
        for dc in dcs:
            if p == 'P1':
                prev_months = [m-1, m]
            else:
                prev_months = [m-1, m]
            expr = 0
            for t_month in prev_months:
                if t_month >= 1 and t_month <=6:
                    if t_month < m:
                        expr += ship_plant_dc[t_month][p][dc]
            model.addConstr(ship_plant_dc[m][p][dc] <= expr, f"Ship_{p}_to_{dc}_max_month_{m}")

# 3. Inventory constraints at DCs
for m in months:
    for dc in dcs:
        # Initial inventory for DC1 in Month 1
        if m == 1 and dc == 'DC1':
            initial_inv = initial_inv_dc1[1]
            expr_initial = sum(initial_inv[t] * (t >= m-2 and t < m) for t in ['Month0', 'Month-1'])
        else:
            expr_initial = 0
        # Inventory balance considering incoming shipments, outgoing shipments, and holding costs
        inv_expr = 0
        for t in [1, 2]:
            if m > 1:
                prev_month_inv = inv_dc_month[m-1][dc][t]
            else:
                prev_month_inv = 0
            new_shipments = ship_plant_dc[m][p][dc] for p in plants
            out_shipments = sum(ship_dc_region[m][dc][r] for r in regions)
            disposal = inv_dc_month[m-1][dc][t-1] * (t == 2) if t >1 else 0
            inv_expr += prev_month_inv + new_shipments - out_shipments - disposal
        model.addConstr(inv_expr <= storage_cap[dc], f"Inv_{dc}_max_month_{m}")

# 4. Demand satisfaction constraints
for m in months:
    for r in regions:
        total_supply = sum(ship_dc_region[m][dc][r] for dc in dcs)
        total_demand = demand[r][m-1]
        unmet = demand_unmet[(m, r)]
        model.addConstr(total_supply + initial_inv.get((m, r), 0) >= total_demand - unmet, f"Demand_{r}_month_{m}")

# 5. Disposal constraints
for m in months:
    for dc in dcs:
        disposed = inv_dc_month[m][dc][1] * 0.5 + inv_dc_month[m][dc][2]
        model.addConstr(disposed <= disposal_cost, f"Disposal_{dc}_month_{m}")

# Objective function
total_cost = 0

# Fixed costs for DCs
for m in months:
    for dc in dcs:
        total_cost += fixed_cost[dc] * d_open[(m, dc)]

# Transportation costs from plants to DCs
for m in months:
    for p in plants:
        for dc in dcs:
            total_cost += transp_cost_plant_dc[(p, dc)] * ship_plant_dc[m][p][dc]

# Inventory holding costs at DCs
for m in months:
    for dc in dcs:
        for t in [1, 2]:
            total_cost += holding_cost[dc] * inv_dc_month[m][dc][t]

# Disposal costs
for m in months:
    for dc in dcs:
        disposed = inv_dc_month[m][dc][1] + inv_dc_month[m][dc][2]
        total_cost += disposal_cost * disposed

# Shortage costs
for m in months:
    for r in regions:
        total_cost += shortage_cost * demand_unmet[(m, r)]

model.setObjective(total_cost, GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
```

